#include "parent_update_pipeline.h"
int fa18_run_parent_update_pipeline(const FA18ParentUpdatePipeline*p){FA18ParentPostflightSetupRoute r;if(!p||fa18_run_parent_update_prefix(p->prefix_state,p->prefix_ops)||fa18_run_parent_update_middle(p->middle_state,p->middle_ops)||fa18_run_parent_flight_update(p->flight_state,p->flight_ops,p->flight_route))return -1;p->postflight_state->local_frame=p->prefix_state->local_frame;p->activity_state->local_frame=p->prefix_state->local_frame;p->tail_state->local_frame=p->prefix_state->local_frame;if(fa18_run_parent_postflight_setup(p->postflight_state,p->postflight_ops,&r))return -1;if(r==FA18_PARENT_POSTFLIGHT_CONTINUE_ACTIVITY&&fa18_run_parent_activity_stages(p->activity_state,p->activity_ops))return -1;return fa18_run_parent_update_tail(p->tail_state,p->tail_ops);}
